// The installed `/eccx-*` commands for the "Vòng lặp" tab (GET /api/loops `commands`): Claude Code's
// `~/.claude/commands/eccx-*.md` and omp's `~/.omp/agent/commands/eccx-*.md`, generated by
// scripts/eccx-gen.py. Only the head of each file is read (frontmatter, heading, `Scope:`), never sent
// whole. Tested in tests/eccx.test.ts.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { eccxKind, sortEccx, type EccxCommand, type EccxEngine } from "../eccx";
import { commandDescription } from "./commands";

const HEAD_MAX = 4096;
const PER_SOURCE_MAX = 120;
const NAME_RE = /^eccx-[a-z0-9][a-z0-9-]{0,48}$/;

type Head = { name: string; engine: EccxEngine; description: string; hint: string; title: string | null; scope: string | null };

/** Frontmatter `argument-hint`, heading title (after " — ") and `Scope:` of a command file's head. */
export function parseEccxHead(text: string): { hint: string; title: string | null; scope: string | null } {
  const src = text.replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n");
  const fm = /^---\n([\s\S]*?)\n---(?:\n|$)/.exec(src);
  const hintLine = fm?.[1].split("\n").find((l) => /^argument-hint\s*:/.test(l));
  const hint = (hintLine?.replace(/^argument-hint\s*:\s*/, "").trim().replace(/^(['"])(.*)\1$/, "$2") ?? "").slice(0, 160);
  const body = fm ? src.slice(fm[0].length) : src;
  const h1 = /^#\s+\/\S+\s+[—-]\s+(.+)$/m.exec(body)?.[1].trim() ?? null;
  // The loop heading reads "Frontend, looped until green": the title is the part before the comma.
  const title = h1 ? h1.replace(/,\s*looped until green$/i, "").slice(0, 60) : null;
  // "Scope: <list>." then, for some categories, a note sentence: the scope ends at the first ". " (".NET" stays whole).
  const scope = /^Scope:\s*(.+?)\.(?:\s|$)/m.exec(body)?.[1].slice(0, 200) ?? null;
  return { hint, title, scope };
}

function readDir(dir: string, engine: EccxEngine): Head[] {
  let names: string[];
  try {
    names = fs.readdirSync(dir);
  } catch {
    return [];
  }
  const out: Head[] = [];
  for (const f of names.sort()) {
    if (!f.endsWith(".md")) continue;
    const name = f.slice(0, -3);
    if (!NAME_RE.test(name)) continue;
    let text: string;
    try {
      const fd = fs.openSync(path.join(dir, f), "r");
      try {
        const buf = Buffer.alloc(HEAD_MAX);
        text = buf.subarray(0, fs.readSync(fd, buf, 0, HEAD_MAX, 0)).toString("utf8");
      } finally {
        fs.closeSync(fd);
      }
    } catch {
      continue;
    }
    out.push({ name, engine, description: commandDescription(text), ...parseEccxHead(text) });
    if (out.length >= PER_SOURCE_MAX) break;
  }
  return out;
}

/** Every installed eccx command once (merged across engines), loops first. */
export function listEccx(home = os.homedir()): EccxCommand[] {
  const heads = [...readDir(path.join(home, ".claude", "commands"), "claude"), ...readDir(path.join(home, ".omp", "agent", "commands"), "omp")];
  const loops = new Set(heads.filter((h) => h.name.startsWith("eccx-loop-")).map((h) => h.name.slice("eccx-loop-".length)));
  const byName = new Map<string, EccxCommand>();
  for (const h of heads) {
    const had = byName.get(h.name);
    if (had) {
      if (!had.engines.includes(h.engine)) had.engines.push(h.engine);
      had.scope ??= h.scope;
      continue;
    }
    // A category has a loop or a `Scope:` line (scripts/eccx-gen.py body); `/eccx-clear` has neither.
    const { kind, cat } = eccxKind(h.name, loops.has(h.name.slice("eccx-".length)) || h.scope != null);
    byName.set(h.name, { name: h.name, kind, cat, title: h.title ?? cat ?? h.name, scope: h.scope, description: h.description, hint: h.hint, engines: [h.engine] });
  }
  // The loop heading always names the category ("Cross-category, looped until green"; eccx-full's own
  // heading is a sentence), the plan file carries the `Scope:` line: each side lends the other its part.
  for (const c of byName.values()) {
    if (c.kind !== "loop") continue;
    const plan = byName.get(`eccx-${c.cat}`);
    if (plan) {
      plan.title = c.title;
      c.scope ??= plan.scope;
    }
  }
  return sortEccx([...byName.values()]);
}

const TTL_MS = 30_000;
let cache: { at: number; home: string; v: EccxCommand[] } | null = null;

/** [listEccx], read again at most every 30 s (the tab polls). */
export function cachedEccx(home = os.homedir(), now = Date.now()): EccxCommand[] {
  if (!cache || cache.home !== home || now - cache.at > TTL_MS) cache = { at: now, home, v: listEccx(home) };
  return cache.v;
}
